import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1174, own='cte_97.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 751 Law Enforcement II ----
H("751.d.1.A",3,"In Law Enforcement II, a student reads a role-play partner's folded arms, clenched jaw and pacing. The student is evaluating:","body language and gestures",["tax forms","radio codes","badge numbers"],"Nonverbal cues add meaning to words.")
H("751.d.1.A",4,"A suspect says 'I'm fine' but trembles and avoids eye contact. The officer should treat the gestures as:","clues to weigh with other facts",["proof of a crime","irrelevant noise","a confession"],"Body language is a clue, not proof.")
H("751.d.1.B",3,"An advanced student calmly restates an upset neighbor's complaint before offering options. This is:","interpersonal communication skill",["avoiding the neighbor","writing a ticket","a use of force"],"Restating shows understanding.")
H("751.d.1.B",4,"Which approach best builds rapport during a citizen contact?","Using a respectful tone and listening before directing",["Raising your voice at once","Ignoring questions","Speaking only in code"],"Respect and listening build cooperation.")
H("751.d.1.C",3,"At a mock burglary, a student jots times, addresses and quotes in a pocket notebook to use later in a report. This is:","effective field note taking",["daydreaming","filing a lawsuit","parking"],"Notes preserve details for reports.")
H("751.d.1.C",4,"Field notes are most useful when they are written:","at or near the time events happen, in clear facts",["a month later from memory","as opinions only","in secret symbols"],"Prompt, factual notes are most reliable.")
H("751.d.1.D",3,"A class designs a scenario in which two officers approach a parked car and arrest a driver with an outstanding warrant. This uses:","patrol tactics to effect an arrest",["classroom seating","traffic counts","budget planning"],"Scenarios rehearse arrest tactics.")
H("751.d.1.D",4,"A good patrol arrest scenario includes assigning roles such as contact officer and:","cover officer",["spectator","vendor","lawyer"],"Cover officer protects the contact officer.")
H("751.d.1.E",3,"A student matches 'detention facility', 'dispatcher' and 'bailiff' to their meanings. This is learning:","law, public safety, corrections and security terms",["cooking words","music terms","sports slang"],"Correct vocabulary aids clear communication.")
H("751.d.1.E",4,"Which term names a person who keeps order in a courtroom?","bailiff",["dispatcher","jailer's cook","mechanic"],"Bailiffs maintain courtroom security.")
H("751.d.2.A",3,"A cadet checks that a handheld radio's battery is charged and the channel set before patrol. This supports:","use of mobile and handheld radio systems",["print shop work","cooking","filing taxes"],"Reliable radios need preparation.")
H("751.d.2.A",4,"Before leaving on patrol, an officer should test the radio so that:","contact with dispatch is assured",["the siren is quieter","the car is cleaner","fuel lasts longer"],"A radio check confirms communication.")
H("751.d.2.B",3,"Over a practice radio, a student spells a license plate as 'Adam, Baker, Charlie' to prevent confusion. This is the:","phonetic alphabet",["Morse flag code","tax code","shorthand grammar"],"Phonetic words clarify letters.")
H("751.d.2.B",4,"Why do officers use the phonetic alphabet on the radio?","Letters like B and D sound alike over static",["It saves paper","It is a tradition only","It sounds friendly"],"Phonetics avoid mishearing.")
H("751.d.2.C",3,"A student runs a plate check through a patrol car's laptop in a drill. This is using:","mobile data computers for communication",["a typewriter","a pager","a fax"],"MDCs send and receive data.")
H("751.d.2.C",4,"A key benefit of sending a records check by data terminal instead of voice is that it:","reduces radio traffic and keeps information more private",["is always faster than thought","needs no training","removes the need for dispatch"],"Data traffic frees the air.")
H("751.d.2.D",3,"A supervisor warns officers not to discuss sensitive details on open radio channels where scanners can listen. This evaluates:","safety concerns with telecommunications equipment",["fashion","fuel cost","parking"],"Open channels can be monitored.")
H("751.d.2.D",4,"Which practice improves safety when using a radio near a tense scene?","Keeping transmissions short and avoiding sensitive details",["Talking continuously","Broadcasting suspect names","Turning volume to maximum"],"Brief, careful traffic is safer.")
H("751.d.2.E",3,"A dispatcher must decide whether to send the next unit to a loud-music complaint or a person reporting a robbery in progress. This shows the need to:","prioritize calls for service",["ignore calls","answer in order only","hang up"],"Life-threatening calls come first.")
H("751.d.2.E",4,"Which call should normally receive the highest priority?","a crime in progress with a threat to life",["a barking dog report","a lost-property inquiry","a parking complaint"],"Threat to life is first.")
H("751.d.2.F",3,"During a hurricane, communications centers use special procedures to coordinate many agencies. These are:","procedures for emergency communications incidents",["daily routines only","recreation plans","hiring steps"],"Disasters require emergency communication plans.")
H("751.d.2.F",4,"In a major emergency, dispatch centers often keep communication working by:","using backup channels and trained emergency procedures",["shutting down","using no radios","waiting for power only"],"Backups sustain communications.")
H("751.d.3.A",3,"A student mapping a trial names the judge, prosecutor, defense attorney, bailiff and clerk. These make up the:","courtroom work group",["jury only","audience","press pool"],"Each role has a job.")
H("751.d.3.A",4,"In the courtroom work group, the prosecutor represents:","the state",["the defendant","the officer personally","the jury"],"Prosecutors act for the state.")
H("751.d.3.B",3,"The night before testifying, an officer rereads field notes, the report and the evidence log. This shows the importance of:","reviewing notes, reports and evidence before testifying",["skipping prep","guessing at details","memorizing opinions"],"Review keeps testimony accurate.")
H("751.d.3.B",4,"Reviewing a report before court helps an officer:","testify accurately and consistently",["change the facts","avoid questions","skip the trial"],"Consistency supports credibility.")
H("751.d.3.C",3,"In a mock trial, an officer identifies a recovered knife and explains how it was packaged and stored so it can be admitted. This is:","properly introducing evidence for admission",["hiding evidence","discarding evidence","guessing"],"Foundation shows the item is what it claims.")
H("751.d.3.C",4,"To admit an item of evidence, the officer must usually show:","what it is and the chain of custody",["its price","its color preference","a verbal rumor"],"Authenticity and custody matter.")
H("751.d.3.D",3,"A student practices answering a cross-examination question by listening, pausing and giving only a truthful, direct answer. This is:","effective courtroom testimony",["arguing with the lawyer","guessing","volunteering opinions"],"Direct, truthful answers are best.")
H("751.d.3.D",4,"When a lawyer asks a question an officer doesn't understand, the officer should:","ask for the question to be repeated or clarified",["guess an answer","walk out","argue"],"Clarity prevents errors.")
H("751.d.3.E",3,"An officer arrives at court in a clean uniform, speaks respectfully and stays calm under tough questions. This shows:","professionalism in demeanor and appearance",["carelessness","hostility","indifference"],"Demeanor affects credibility.")
H("751.d.3.E",4,"Jurors often judge an officer's credibility partly by the officer's:","professional demeanor and appearance",["favorite sport","car model","hometown"],"Professional presentation builds trust.")
H("751.d.3.F",3,"Before a trial, the arresting officer meets the prosecutor to go over the facts and likely questions. This is a:","pre-trial meeting with a prosecutor",["social visit","vacation","parking review"],"Prep meetings clarify the case.")
H("751.d.3.F",4,"A pre-trial meeting helps the prosecutor by:","identifying strengths, weaknesses and needed evidence",["avoiding the case","replacing the judge","hiding facts"],"Meetings guide trial preparation.")
H("751.d.4.A",3,"An instructor compares open questions, reflective listening and calm tone as methods officers use to communicate. These are:","interpersonal communication techniques in law enforcement",["traffic laws","courtroom seating","uniform rules"],"Technique supports effective contact.")
H("751.d.4.A",4,"An officer says 'It sounds like you're worried about your son.' This technique is called:","reflective listening",["interrogation","citation writing","evidence tagging"],"Reflecting feelings shows understanding.")
H("751.d.4.B",3,"A person who stays silent and agrees but later sulks is acting:","passive-aggressively",["assertively","aggressively","openly"],"Passive-aggressive behavior is indirect.")
H("751.d.4.B",4,"Which statement is assertive rather than aggressive?","'I need you to step back so we can both stay safe.'",["'Back off or else!'","'Whatever, I don't care.'","'Do it, you fool!'"],"Assertive is clear and respectful.")
H("751.d.4.C",3,"A rude, shouting caller won't listen. A good officer lowers voice, stays courteous and sets clear limits. This is:","a strategy for dealing with difficult people",["matching the shouting","ending the call","ignoring the caller"],"Calm limits de-escalate.")
H("751.d.4.C",4,"A useful first step with an angry person is to:","stay calm and let them vent briefly before directing",["argue back","threaten arrest at once","walk away"],"Letting them vent often cools anger.")
H("751.d.4.D",3,"Fear, pain, intoxication, and feeling disrespected can all raise a person's anger. These are:","factors contributing to hostility",["traffic laws","budget lines","clothing styles"],"Understanding causes aids response.")
H("751.d.4.D",4,"Knowing why a person is hostile helps an officer to:","choose a response that lowers tension",["raise tension","excuse crime","skip reports"],"Causes shape the best approach.")
H("751.d.5.A",3,"In a drill, a trained negotiator talks calmly to a barricaded subject to end the standoff without injury. This is:","crisis negotiation",["raiding","traffic control","patrol parking"],"Negotiation prioritizes safety.")
H("751.d.5.A",4,"The main goal of crisis negotiation is to:","resolve the incident peacefully",["win an argument","punish quickly","avoid contact"],"Peaceful resolution protects lives.")
H("751.d.5.B",3,"Students rotate as primary negotiator, coach and recorder in a simulation. This is serving as a:","crisis negotiation team member",["spectator","bystander","witness only"],"Teams share roles.")
H("751.d.5.B",4,"On a negotiation team, the coach mainly:","advises and supports the primary negotiator",["kicks in doors","fills out ticketing","directs traffic"],"Coaches support the negotiator.")
H("751.d.5.C",3,"A negotiator uses a steady voice, active listening and open-ended questions with an upset subject. These are:","effective communication techniques for crisis negotiation",["arguments","threats","orders only"],"Calm technique builds trust.")
H("751.d.5.C",4,"Which negotiator statement best builds trust?","'Help me understand what's happening for you.'",["'You have no choice.'","'Stop talking.'","'You're being foolish.'"],"Open invitations encourage talk.")
H("751.d.5.D",3,"While negotiating, a team confirms that hostages are alive and unharmed before agreeing to any demand. This is a:","hostage safety consideration",["paperwork step","budget step","media step"],"Verifying safety is critical.")
H("751.d.5.D",4,"Hostage safety is best protected when negotiators:","keep communication open and avoid actions that provoke harm",["make rash promises","cut contact","raise the threat"],"Steady contact lowers risk.")
H("751.d.5.E",3,"A negotiator weighs a subject's request for a car against the risk to the public if he escapes. This differentiates:","public safety from individual rights",["wages from taxes","day from night","food from drink"],"Safety and rights must be balanced.")
H("751.d.5.E",4,"In a crisis, an officer may limit a person's freedom only when:","the law and the safety threat justify it",["the person is unpopular","the officer is annoyed","it is convenient"],"Rights are limited only with legal reason.")
H("751.d.6.A",3,"An officer tells a theft victim about filing a protective order and seeking restitution. This demonstrates:","advising crime victims of legal recourse",["ignoring victims","closing a case","writing a ticket"],"Victims are informed of options.")
H("751.d.6.A",4,"Legal recourse for a crime victim may include:","seeking restitution or compensation through the court",["avoiding the courts","dropping the report","blaming the victim"],"Restitution is a recourse.")
H("751.d.6.B",3,"A student charts the steps from arrest to arraignment to trial for a suspect, victim and witness. This explains:","step-by-step court procedures",["school discipline","tax filing","hiring"],"Procedure guides participants.")
H("751.d.6.B",4,"A witness receiving a subpoena is being told to:","appear and testify at a stated time",["avoid the court","pay a fine","hire a lawyer"],"A subpoena compels appearance.")
H("751.d.6.C",3,"An officer calls for an interpreter and speaks slowly while helping a hearing-impaired and a non-English-speaking person. This is:","appropriate assistance to individuals with special needs",["ignoring them","delaying service","skipping reports"],"Accommodation ensures access.")
H("751.d.6.C",4,"When assisting a person with a disability, an officer should:","communicate respectfully and provide reasonable accommodation",["talk over them","rush","avoid contact"],"Respect and accommodation matter.")
H("751.d.6.D",3,"An investigator reports to a scene involving a child victim and a victim of an elder-abuse report, following special steps. This is a:","preliminary investigation of a special-victim case",["traffic stop","parking call","noise complaint"],"Special victims need special procedures.")
H("751.d.6.D",4,"In a preliminary investigation, the officer first:","ensures safety, aids the victim and secures the scene",["closes the case","leaves","writes final reports"],"Safety and aid come first.")
H("751.d.6.E",3,"An officer plans to personally tell a family that their relative was killed in a crash, using a calm, clear and caring approach. This is a:","death notification",["warrant service","traffic stop","patrol briefing"],"Death notifications require care.")
H("751.d.6.E",4,"A good death notification is:","done in person, promptly and with compassion",["sent by text","delayed for months","done by a stranger by phone"],"In-person delivery shows respect.")
H("751.d.6.F",3,"A state law requires officers to give crime victims written information on their rights and services. This is a:","legal requirement of law enforcement toward victims",["suggestion","rumor","hobby"],"Officers must follow statutory duties.")
H("751.d.6.F",4,"Giving victims required notices and referrals is an example of:","meeting legal duties owed to crime victims",["optional courtesy","personal choice","unrelated work"],"Law requires victim notices.")
H("751.d.7.A",3,"An instructor explains that Texas law lets officers make an arrest without a warrant in certain family violence cases. This is a:","technique to enforce domestic violence laws",["traffic law","civil trial","school rule"],"Enforcement tools exist in law.")
H("751.d.7.A",4,"At a domestic violence call, enforcing the law includes:","separating the parties and determining the primary aggressor",["ignoring the call","taking sides by sex","leaving at once"],"Primary-aggressor analysis guides arrest.")
H("751.d.7.B",3,"In a role-play, two officers calm a shouting couple by separating them and speaking quietly. This is:","defusing a simulated domestic violence incident",["escalating a fight","ignoring a call","writing tickets"],"De-escalation lowers risk.")
H("751.d.7.B",4,"A key step in defusing a heated domestic dispute is to:","separate the people and keep a calm voice",["take sides","shout orders","leave weapons in reach"],"Separation and calm help.")
H("751.d.7.C",3,"After finding probable cause that an assault occurred in a home, an officer decides to arrest. This is:","applying law in making an arrest",["a guess","a favor","a trial"],"Probable cause supports arrest.")
H("751.d.7.C",4,"An arrest requires that an officer have:","probable cause or a valid warrant",["a hunch","a complaint about noise","a rumor"],"Probable cause or a warrant is required.")
H("751.d.8.A",3,"A civil paper server studies garnishment and attachment. These are examples of:","civil law procedures",["criminal charges","traffic laws","school policy"],"Civil procedures involve property and claims.")
H("751.d.8.A",4,"A court order that takes part of a debtor's wages to pay a debt is called:","garnishment",["bail","parole","probation"],"Garnishment collects debts.")
H("751.d.8.B",3,"An officer serving civil papers may not break into a home to do so. This identifies:","limits on force and entry in civil procedures",["no limits","unlimited power","criminal arrest rules"],"Civil process has strict limits.")
H("751.d.8.B",4,"In civil process service, an officer generally may not:","use force to enter a private home without legal authority",["knock politely","hand over papers","record the time"],"Force and entry are restricted.")
H("751.d.8.C",3,"A class compares a protective order from a family court, a no-contact condition of bond and a restraining order. This differentiates:","types of protective and no-contact orders",["traffic tickets","diplomas","vehicle titles"],"Order types differ in source and scope.")
H("751.d.8.C",4,"A no-contact order set as a condition of bond usually:","bars the defendant from contacting the victim",["frees the defendant","ends the case","appoints a lawyer"],"Bond conditions can prohibit contact.")
H("751.d.8.D",3,"A student studies when an officer may take a person in crisis to a hospital for evaluation without a criminal charge. This identifies:","requirements for emergency mental health evaluation",["traffic rules","jury rules","tax rules"],"Emergency detention follows legal criteria.")
H("751.d.8.D",4,"An officer may detain someone for emergency mental health evaluation if the person:","appears mentally ill and presents a substantial risk of harm",["is just rude","is late","is unpopular"],"Risk of harm is key.")
H("751.d.9.A",3,"A student studies the Texas Alcoholic Beverage Code on who may sell, serve and consume alcohol. This explains:","alcohol and beverage laws and procedures",["parking laws","housing law","school law"],"The code governs alcohol.")
H("751.d.9.A",4,"The state agency that regulates alcohol sales in Texas is the:","Texas Alcoholic Beverage Commission",["Texas Education Agency","Texas Lottery Board","Texas Parks Board"],"TABC enforces alcohol law.")
H("751.d.9.B",3,"The Texas code defines beer, wine and liquor above a set alcohol content. These are:","alcoholic beverages",["soft drinks","juices","teas"],"Definitions set what is regulated.")
H("751.d.9.B",4,"Under Texas law, an alcoholic beverage includes:","beer, wine and distilled spirits",["only water","only juice","only milk"],"Alcohol covers several types.")
H("751.d.9.C",3,"A clerk who sells beer to a 17-year-old is making an illegal sale, while one who checks ID and sells to a 25-year-old is making a legal sale. This differentiates:","legal and illegal alcohol sales",["jobs","wages","shifts"],"Age and licensing determine legality.")
H("751.d.9.C",4,"Selling alcohol to a minor is generally:","illegal",["legal","required","encouraged"],"Sales to minors are prohibited.")
H("751.d.9.D",3,"An adult drinks a glass of wine at a licensed restaurant. This is a circumstance where alcohol:","may be legally consumed",["is always illegal","is a crime","is banned in all places"],"Legal consumption occurs in permitted settings by adults.")
H("751.d.9.D",4,"Under Texas law, alcohol may be legally consumed by:","adults of legal drinking age in permitted places",["anyone in a school","minors at parties","drivers on the road"],"Age and place matter.")
H("751.d.10.A",3,"At the roadside, a student guides a volunteer through the Horizontal Gaze Nystagmus test and the walk-and-turn. These are:","standardized field sobriety tests",["math quizzes","eye charts","fitness drills"],"SFSTs help detect impairment.")
H("751.d.10.A",4,"The three standardized field sobriety tests are HGN, walk-and-turn and:","one-leg stand",["jump rope","sprint","swim test"],"The third test is the one-leg stand.")
H("751.d.10.B",3,"A driver weaves, brakes late and drifts across lines. These are:","indicators of impaired driving",["good driving habits","signs of skill","normal practices"],"Erratic driving suggests impairment.")
H("751.d.10.B",4,"Which is a common indicator of an impaired driver?","driving without headlights at night",["signaling a turn","staying in lane","obeying the speed limit"],"Missing headlights at night is a cue.")
H("751.d.10.C",3,"Officers use patrol observation, sobriety checkpoints and breath tests to find impaired drivers. These are:","methods to detect and apprehend impaired drivers",["tax methods","school methods","filing methods"],"Detection uses observation and tests.")
H("751.d.10.C",4,"A device that measures breath alcohol at the roadside is a:","preliminary breath test device",["radar gun","stop stick","flashlight"],"PBTs estimate BAC.")
H("751.d.10.D",3,"After a DWI arrest, an officer writes a detailed report and gathers video, test results and statements for court. This is:","preparing evidence and reports for DWI testimony",["skipping paperwork","guessing","closing the case"],"Documentation supports testimony.")
H("751.d.10.D",4,"In a DWI case, the officer's report should record:","observed driving, test results and statements",["opinions about the driver's character","the officer's lunch","the car's resale value"],"Facts support prosecution.")
H("751.d.11.A",3,"At a large protest, a supervisor orders pepper spray and bean bag rounds be deployed only under strict policy. This is:","deployment of less-than-lethal and chemical crowd control",["handing out water","traffic control","patrol briefings"],"Crowd control tools are regulated.")
H("751.d.11.A",4,"Less-than-lethal options are meant to:","gain compliance with a lower risk of death",["cause maximum harm","replace training","avoid reports"],"They reduce the risk of fatality.")
H("751.d.11.B",3,"Before deploying at an event, commanders assess crowd size, mood, exits and officer safety. This is a:","needs assessment for crowd management",["parking review","menu check","payroll check"],"Assessment guides tactics.")
H("751.d.11.B",4,"A crowd management assessment should include:","crowd size, mood and available escape routes",["the weather forecast only","the price of tickets","the band's playlist"],"Conditions affect planning.")
H("751.d.11.C",3,"Officers set up barricades and lines to keep a march away from a hospital entrance. This is:","establishing perimeters for crowd control",["parking","filming","debating"],"Perimeters control movement.")
H("751.d.11.C",4,"A perimeter in crowd control helps to:","contain the area and protect people and property",["start a riot","block officers","hide evidence"],"Perimeters limit spread.")
H("751.d.11.D",3,"An officer spots the organizer who is calming people, the agitators and bystanders needing protection. This shows the need to identify:","group leaders, followers and victims",["clothing styles","weather","music"],"Roles shape response.")
H("751.d.11.D",4,"Identifying a crowd's leaders can help officers to:","communicate and de-escalate through them",["arrest everyone","ignore the crowd","avoid talking"],"Leaders can influence crowd behavior.")
H("751.d.12.A",3,"In a drill, an officer moves from presence and verbal commands to hands-on control as a subject escalates. This demonstrates:","the force continuum",["a rule of grammar","a map","a ledger"],"The continuum matches force to resistance.")
H("751.d.12.A",4,"Under the force continuum, an officer should use:","only the level of force reasonably needed",["the highest force first","no force ever","random force"],"Force must be proportional.")
H("751.d.12.B",3,"State and federal courts and legislatures set limits on when officers may use force. These are:","guidelines and restrictions on force by governments",["suggestions","jokes","menu items"],"Government rules limit force.")
H("751.d.12.B",4,"In Graham v. Connor, the Supreme Court said officers' force is judged by:","objective reasonableness",["officer intent","public opinion","the outcome only"],"Reasonableness standard.")
H("751.d.12.C",3,"An officer's authority to use force comes from statutes such as the Texas Penal Code Chapter 9. This identifies:","the legal authority for use of force",["a dress code","an overtime rule","a memo"],"Law grants limited authority.")
H("751.d.12.C",4,"Chapter 9 of the Texas Penal Code deals with:","justification excluding criminal responsibility, including use of force",["tax law","marriage law","parking law"],"Chapter 9 sets justification.")
H("751.d.12.D",3,"After using a baton, an officer must explain why the force was needed and whether it was reasonable. This is:","evaluating less-than-lethal force",["avoiding review","hiding facts","writing poetry"],"Use of force is reviewed.")
H("751.d.12.D",4,"A less-than-lethal force review asks whether the force was:","reasonable for the threat faced",["colorful","fashionable","popular"],"Reasonableness is the test.")
H("751.d.12.E",3,"A review board studies whether an officer who fired a weapon faced an imminent threat of death or serious injury. This is:","evaluating deadly force",["traffic review","budget review","payroll review"],"Deadly force requires grave threat.")
H("751.d.12.E",4,"Deadly force is generally justified only to stop:","an imminent threat of death or serious bodily injury",["a minor theft","a verbal argument","a parking violation"],"Deadly force is a last resort.")
H("751.d.13.A",3,"A student practices a pat-down of a role-player immediately after an arrest to find weapons and evidence. This is:","a search incident to arrest",["a random frisk","a home search","a checkpoint"],"Search incident to arrest is lawful.")
H("751.d.13.A",4,"The two main purposes of a search incident to arrest are officer safety and:","preserving evidence",["raising cash","taking property","embarrassment"],"Safety and evidence justify it.")
H("751.d.13.B",3,"An officer seat-belts a prisoner, checks the back seat before and after the trip and keeps the prisoner in view. This is:","safe transport without violating personal rights",["neglect","careless driving","ignoring rights"],"Safe, lawful transport.")
H("751.d.13.B",4,"Before placing a prisoner in a patrol car, an officer should:","search the back seat for items left behind",["skip the search","open the windows","remove the seat belts"],"Prisoners can hide items.")
H("751.d.13.C",3,"A cadet compares handcuffs, flex cuffs and leg restraints for a transport. This is:","methods of restraining a person during transport",["hiding evidence","traffic control","radio use"],"Restraints must be proper and safe.")
H("751.d.13.C",4,"When using handcuffs, an officer should check that they:","are secure but not too tight and are double-locked",["are loose","are rusty","are removed"],"Check fit and lock.")
H("751.d.13.D",3,"An officer drives a lost 9-year-old home and a juvenile in custody to a detention center. This is:","transporting non-custodial persons and juveniles",["a pursuit","a stakeout","a parade"],"Different people require different procedures.")
H("751.d.13.D",4,"Compared with transporting an adult prisoner, transporting a juvenile usually requires:","following juvenile procedures and separating from adults",["no policy","mixing with adults","skipping notice"],"Juvenile rules apply.")
H("751.d.14.A",3,"Two students practice a calm, structured interview with a witness and a more formal interrogation of a suspect. This demonstrates:","interviewing and interrogation techniques",["traffic control","filing","parking"],"Techniques differ by role.")
H("751.d.14.A",4,"An interview differs from an interrogation in that an interview is generally:","information-gathering and non-accusatory",["forceful","secret","illegal"],"Interviews gather information.")
H("751.d.14.B",3,"A trainee practices gentle, age-appropriate questions with a child who witnessed a crime. This is:","simulating interviews of rape victims and child witnesses",["aggressive questioning","skipping the child","a trial"],"Sensitive interviews need care.")
H("751.d.14.B",4,"When interviewing a child victim, officers should:","use simple language and avoid leading questions",["use legal terms","pressure the child","suggest answers"],"Avoid leading and confusing language.")
H("751.d.15.A",3,"A student photographs tire marks, notes road conditions and measures vehicle positions at a mock crash. This is:","recording crash scene evidence with standard procedures",["cleaning the road","skipping evidence","ignoring marks"],"Standard reports preserve evidence.")
H("751.d.15.A",4,"At a crash scene, an officer should record:","measurements, positions and photographs",["opinions only","gossip","guesses"],"Facts are recorded.")
H("751.d.15.B",3,"A class applies traffic laws to skid marks and impact points to find who was at fault. This is:","analyzing crash scene evidence using laws and procedures",["guessing","ignoring evidence","spreading rumors"],"Analysis ties evidence to law.")
H("751.d.15.B",4,"Analyzing a crash scene involves comparing evidence to:","traffic law and standard investigation procedures",["rumors","fashion trends","radio ads"],"Evidence is evaluated under law.")
H("751.d.15.C",3,"A student uses a skid distance and friction value to estimate a vehicle's speed. This is:","calculating speed, velocity, time and distance",["story writing","drawing","dancing"],"Math estimates speed.")
H("751.d.15.C",4,"If a car travels 60 feet in 2 seconds, its average speed is:","30 feet per second",["120 feet per second","62 feet per second","58 feet per second"],"Speed = distance/time.")
H("751.d.15.D",3,"Using a template, a student draws a top-view scale diagram of two cars at impact. This is:","drawing scale diagrams of simulated collisions",["painting","sketching a pet","tracing a map"],"Scale diagrams show positions.")
H("751.d.15.D",4,"If 1 inch on a diagram represents 10 feet, a car 20 feet from a curb is drawn:","2 inches from the curb",["10 inches","20 inches","0.5 inches"],"20 ÷ 10 = 2.")
H("751.d.15.E",3,"A trainee studies gouge marks, debris fields and final rest positions to explain how a collision happened. This is:","interpreting crash scene evidence",["ignoring evidence","guessing","burying clues"],"Evidence tells the story.")
H("751.d.15.E",4,"A debris field after a crash helps investigators find:","the area of impact",["the driver's job","the weather forecast","the car's age"],"Debris marks impact area.")
H("751.d.16.A",3,"At a multi-agency exercise, one commander directs police, fire and EMS under a common structure. This shows knowledge of the:","incident command system",["traffic system","payroll system","grading system"],"ICS organizes response.")
H("751.d.16.A",4,"The incident commander is responsible for:","overall management of the incident",["only traffic","only cleanup","only media"],"IC has overall responsibility.")
H("751.d.16.B",3,"During a tornado response, police coordinate with local, state and federal agencies and private utility crews. This is:","coordinating with response partners at all levels of government and the private sector",["working alone","competing","avoiding help"],"Partnership is needed.")
H("751.d.16.B",4,"Coordination among agencies matters in a large disaster because it:","avoids duplication and gaps in response",["slows response","adds confusion","blocks help"],"Coordination improves efficiency.")
H("751.d.16.C",3,"Students review ICS features such as unity of command and manageable span of control in a tabletop. This is:","evaluating ICS applications and organizational principles",["a snack break","an exam","a parade"],"Principles shape structure.")
H("751.d.16.C",4,"In ICS, 'span of control' refers to:","the number of people one supervisor can effectively manage",["the length of a hose","the radius of a fire","the range of a radio"],"A supervisor oversees about 3 to 7.")
H("751.d.16.D",3,"A class uses FEMA's incident command structure to set up planning, operations, logistics and finance sections for a mock flood. This is:","applying the FEMA incident command structure",["random planning","skipping roles","ignoring structure"],"ICS sections handle functions.")
H("751.d.16.D",4,"The ICS section that tracks costs and compensation is:","Finance/Administration",["Operations","Planning","Safety"],"Finance handles costs.")
H("751.d.17.A",3,"A student reads placards and identifies a flammable liquid versus a corrosive. This is:","identifying and classifying hazardous materials",["parking","mapping","photography"],"HazMat has classes.")
H("751.d.17.A",4,"A diamond-shaped placard on a truck is used to:","show the type of hazard being carried",["advertise","show weight","show origin"],"Placards communicate hazard classes.")
H("751.d.17.B",3,"In a drill with a suspicious device, officers evacuate, keep radios off near it and call the bomb squad. This follows:","protocols for responding to explosive materials",["panicking","touching the device","ignoring"],"Do not touch; evacuate.")
H("751.d.17.B",4,"Officers who find a suspected explosive device should:","isolate the area and call specialized responders",["move it","open it","shake it"],"Specialists handle explosives.")
H("751.d.17.C",3,"Dispatch receives a call that a bomb has been placed in a school. This requires:","procedures for responding to bomb threats and suspicious objects",["ignoring it","giggling","hanging up"],"Threats are taken seriously.")
H("751.d.17.C",4,"When a suspicious package is found, a good first step is to:","evacuate to a safe distance and notify authorities",["tear it open","carry it outside","kick it"],"Distance and notice protect people.")
H("751.d.17.D",3,"Teams sweep a mock building room by room for hidden devices, marking what's searched. This is:","a building and property search for explosives",["a lunch plan","a training exam","an auction"],"Systematic sweeps find devices.")
H("751.d.17.D",4,"During a search for an explosive device, officers should avoid using:","radios or cell phones close to a suspected device",["flashlights","notebooks","clipboards"],"Radio waves can trigger devices.")
H("751.d.17.E",3,"An officer responds to an overturned tanker leaking an unknown liquid and sets up a perimeter upwind. This is:","responding to a hazardous material incident",["a shift change","a parade","a stakeout"],"HazMat response begins with isolation.")
H("751.d.17.E",4,"At a hazmat incident, officers should approach from:","upwind and uphill",["downwind","downhill","inside the cloud"],"Upwind and uphill limit exposure.")
H("751.d.18.A",3,"A student studies how to protect power plants, water systems and bridges from attack. This is:","critical infrastructure protection techniques",["gardening","farming","fashion"],"Infrastructure is vital.")
H("751.d.18.A",4,"Critical infrastructure includes systems such as:","power grids and water supplies",["board games","snack bars","toys"],"They support daily life.")
H("751.d.18.B",3,"A team builds a plan with fences, cameras, patrols and access control for a rail yard. This is:","a plan for protecting a potential target",["a lunch plan","a party plan","a trip plan"],"Layered security protects targets.")
H("751.d.18.B",4,"Layered security for a target includes:","barriers, surveillance and controlled access",["decorations","souvenirs","banners"],"Layers deter attacks.")
H("751.d.19.A",3,"A class explores bomb-disposal robots and body cameras. This is researching:","new technologies used in law enforcement",["old gear","fashion","music"],"Technology changes tactics.")
H("751.d.19.A",4,"A bomb-disposal robot helps officers by:","handling dangerous devices from a safe distance",["writing reports","driving patrol","filing records"],"Robots keep people safe.")
H("751.d.19.B",3,"An experienced officer takes legal updates, tactics refreshers and leadership courses every year. This shows the importance of:","continuing education in law enforcement",["quitting","avoiding change","skipping classes"],"Law and tactics change.")
H("751.d.19.B",4,"Continuing education helps officers because laws and best practices:","change over time",["never change","are always the same","are unimportant"],"Training keeps skills current.")
H("751.d.20.A",3,"A student explains why an officer needs probable cause to stop and arrest a suspect, and reasonable suspicion for a brief stop. This applies:","legal justification and probable cause for field activities",["a guess","a hunch","a rumor"],"Different standards apply.")
H("751.d.20.A",4,"Reasonable suspicion is required for:","a brief investigative stop",["an arrest","a conviction","a sentence"],"Terry stop standard.")
H("751.d.20.B",3,"Two teams practice a misdemeanor stop for a taillight violation and a high-risk stop of a stolen car. This is:","simulating misdemeanor and high-risk traffic stops",["parking","patrol briefings","walking beats"],"Stops differ by risk.")
H("751.d.20.B",4,"During a high-risk stop, officers commonly:","use cover, give commands and approach with caution",["approach casually","use no cover","skip commands"],"High-risk stops require tactics.")
H("751.d.20.C",3,"A department's policy limits when officers may chase a fleeing car, motorcycle or on foot. These are:","pursuit procedures",["lunch rules","sick leave","dress code"],"Pursuits are risky.")
H("751.d.20.C",4,"Before continuing a vehicle pursuit, an officer weighs:","the danger of the chase against the seriousness of the offense",["radio volume","car color","lunch time"],"Risk-benefit decides.")
H("751.d.20.D",3,"A dispatcher says a burglary just happened and then reports a burglary in progress. Students simulate responding to:","a delayed crime and a crime in progress",["a noise only","a parade","a shift change"],"Response differs by timing.")
H("751.d.20.D",4,"Compared with a delayed crime, a crime in progress usually requires:","a faster response to catch the suspect",["a slower response","no response","only a report by mail"],"In progress = urgent.")
H("751.d.20.E",3,"In training, two officers methodically clear a vacant warehouse after an alarm. This is:","conducting a building search",["a vacation","a parade","a drive"],"Building searches use teamwork.")
H("751.d.20.E",4,"A key rule when searching a building is to:","communicate and cover each other while moving",["split up with no contact","run ahead","turn off radios"],"Communication prevents blue-on-blue.")
H("751.d.20.F",3,"An officer arrests a man under a judge's signed warrant, while another arrests a man who just committed a felony in view. This simulates:","warrant and warrantless arrests",["civil service","traffic stops","patrol scheduling"],"Both types are lawful under conditions.")
H("751.d.20.F",4,"A warrantless arrest is generally allowed when an officer:","has probable cause that a crime was committed in their presence",["is bored","has a hunch","received a rumor"],"Offenses in view allow arrest.")
H("751.d.20.G",3,"A class compares how to handle a call with a single officer, a pair, and a team. This differentiates:","procedures for one-person, two-person and multi-officer units",["clothing","vehicles","patrol cars only"],"Staffing changes tactics.")
H("751.d.20.G",4,"A one-person unit responding to a dangerous call should usually:","wait for backup before making contact",["rush in alone","avoid radio","ignore the call"],"Backup improves safety.")
H("751.d.20.H",3,"Students compare how they respond to something they see themselves, a dispatched call, and a call from a citizen at the station. This compares:","patrol responses to on-view and dispatched offenses",["parking","weather","shift length"],"Response varies by source.")
H("751.d.20.H",4,"An on-view offense is one that the officer:","sees personally",["hears about later","reads in the news","is told by letter"],"On-view means witnessed.")
H("751.d.20.I",3,"A cadet in a patrol-car role-play buckles up, checks surroundings and keeps hands visible. This shows being:","safety conscious as a patrol officer",["careless","reckless","distracted"],"Safety habits save lives.")
H("751.d.20.I",4,"Wearing a seat belt and a vest are examples of:","officer safety habits",["fashion","extra duties","rituals"],"Basic safety practices.")
H("751.d.21.A",3,"A class traces how neighborhood foot patrols and citizen partnerships grew from the 1960s to today. This explores the:","development of community policing",["tax reform","prison building","highway design"],"Community policing evolved over time.")
H("751.d.21.A",4,"Community policing grew from the idea that police and citizens should:","work together to solve problems",["avoid each other","compete","hide"],"Partnership is the core.")
H("751.d.21.B",3,"A student studies how an officer stationed at a high school counsels students and teaches safety lessons. This evaluates the:","role of school resource officers",["traffic officers","game wardens","jailers"],"SROs work in schools.")
H("751.d.21.B",4,"A school resource officer serves as a law enforcement officer, a:","teacher and counselor",["cook","bus driver","janitor"],"The SRO triad includes teaching and counseling.")
H("751.d.21.C",3,"A neighborhood service officer helps residents with graffiti, code issues and block meetings. This evaluates the:","role of neighborhood service officers",["traffic court","jail transport","prison guards"],"NSOs build local ties.")
H("751.d.21.C",4,"Neighborhood service officers focus on:","community problems and relationships in one area",["highway chases","court security","evidence storage"],"They address local concerns.")
H("751.d.21.D",3,"A crime prevention officer visits classrooms with a safety-dog mascot to teach children about stranger danger. This evaluates:","the role of crime prevention officers",["traffic officers","jail officers","SWAT"],"Prevention officers educate.")
H("751.d.21.D",4,"The purpose of crime prevention programs like Neighborhood Watch is to:","reduce crime by involving residents",["replace police","ignore crime","spread fear"],"Involved citizens help prevent crime.")
H("751.d.21.E",3,"A department's spokesperson issues a statement and answers reporter questions after a major incident. This evaluates the:","responsibilities of the public information officer",["patrol officer","evidence tech","dispatcher"],"PIOs communicate with the media.")
H("751.d.21.E",4,"A public information officer must make sure that released information is:","accurate and does not harm the investigation",["speculative","gossip","personal opinion"],"Accuracy and care.")
H("751.d.21.F",3,"A team maps burglaries by street and time, then recommends better lighting and neighborhood watch. This is a:","crime prevention analysis",["tax audit","garden plan","menu review"],"Analysis finds patterns.")
H("751.d.21.F",4,"Mapping where and when crimes happen helps officers to:","focus prevention efforts",["guess","delay response","avoid patrol"],"Patterns guide action.")
H("751.d.22.A",3,"A first responder checks the rules for when to enter a crime scene, how long to remain, and when to release it. This identifies:","legal requirements for first responders at a crime scene",["optional ideas","rumors","traffic rules"],"Law controls scene access.")
H("751.d.22.A",4,"A first officer at a crime scene may enter without a warrant to:","aid victims and make the scene safe",["search everything","take souvenirs","clean up"],"Emergency aid is allowed.")
H("751.d.22.B",3,"Before stepping into a scene, a cadet puts on gloves, notes the entry path and tapes off the area. This demonstrates:","procedures before entering and securing a crime scene",["shortcuts","skipping notes","contaminating"],"Pre-entry steps protect evidence.")
H("751.d.22.B",4,"A crime scene boundary is set to:","keep unauthorized people out and protect evidence",["help visitors","show off","delay the case"],"Boundaries preserve evidence.")
H("751.d.22.C",3,"Students use a grid and spiral pattern to search a mock room for evidence. This demonstrates:","a proper crime scene search",["random walking","skipping areas","tossing items"],"Systematic searches avoid misses.")
H("751.d.22.C",4,"Which is a common pattern used to search a crime scene?","a grid or spiral search",["a random walk","a zigzag dance","a skip search"],"Patterns ensure coverage.")
H("751.d.22.D",3,"A technician places numbered tents beside each item before it is collected. This demonstrates:","marking and collecting evidence",["destroying evidence","ignoring items","moving items"],"Marking identifies items.")
H("751.d.22.D",4,"Before an item is moved, it is normally:","photographed and marked in place",["discarded","cleaned","moved first"],"Document position first.")
H("751.d.22.E",3,"A student measures from two fixed points to a bullet casing and sketches the room. This demonstrates:","measuring and sketching evidence and landmarks",["painting","guessing","tracing"],"Measurements fix locations.")
H("751.d.22.E",4,"Using two fixed reference points to record where an item lies is called:","triangulation",["trisection","tetrahedra","trilogy"],"Triangulation fixes position.")
H("751.d.22.F",3,"A photographer takes overall, mid-range and close-up pictures of a scene and a footprint with a scale. This demonstrates:","photographing the scene and evidence",["editing","sketching","painting"],"Photos document scenes.")
H("751.d.22.F",4,"A scale placed next to evidence in a photograph shows:","the item's actual size",["its age","its owner","its value"],"Scales give size reference.")
H("751.d.22.G",3,"Each person who handles a bloody shirt signs a log, and it is sealed in a paper bag. This demonstrates:","chain of custody and proper packaging",["tossing it","hiding it","burning it"],"Custody documents who held it.")
H("751.d.22.G",4,"Biological evidence like a bloody shirt is usually packaged in:","paper bags",["plastic bags","tin cans","glass jars"],"Paper lets moisture escape.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_97.jsonl"))
